    "stabilite": "String"
  },
  "situation_financiere": {
    "dettes": "String",
    "epargne_investissements": "String",
    "niveau_connaissance": "String",
    "autres_donnees": "String"
  },
  "objectifs_projets": {
    "objectif_principal": "String",
    "court_terme": "String",
    "moyen_long_terme": "String"
  },
  "points_douloureux": [
    "String",
    "String"
  ],
  "attentes_formation": {
    "vision_ultime": "String",
    "besoins_specifiques": "String"
  },
  "logistique": {
    "accompagnement": "String",
    "dates_souhaitees": "String",
