// 1. On récupère le texte brut généré par Gemini
// Le chemin dépend de la structure exacte que tu m'as montrée
const rawText = $input.first().json.content.parts[0].text;

// 2. Sécurité : On nettoie le texte au cas où Gemini aurait mis des balises ```json autour
const cleanText = rawText.replace(/```json|```/g, '').trim();

// 3. On convertit le texte en véritable objet JSON utilisable par n8n
return JSON.parse(cleanText);

const rawText = $input.first().json.content.parts[0].text;
const cleanText = rawText.replace(/```json|```/g, '').trim();
return JSON.parse(cleanText);

// 1. Récupération SÉCURISÉE
const inputItem = $input.first();
let rawText;

// On récupère le contenu brut
if (inputItem.json.content && inputItem.json.content.parts && inputItem.json.content.parts[0]) {
    rawText = inputItem.json.content.parts[0].text;
} else if (inputItem.json.text) {
    rawText = inputItem.json.text;
} else {
    rawText = JSON.stringify(inputItem.json);
}

if (typeof rawText !== 'string') rawText = String(rawText);

// --- DÉBALLAGE EN PROFONDEUR (La nouveauté) ---
// On nettoie le Markdown
let content = rawText.replace(/```json|```/g, '').trim();

// On essaie de parser tant que c'est possible pour enlever les couches de JSON/Stringify
try {
    // Premier niveau de parsing
    let parsed = JSON.parse(content);

    // Si c'est un objet, on cherche le corps
    if (typeof parsed === 'object' && parsed !== null) {
        // Gestion du cas complexe (Tableaux, types...)
        if (parsed.corps && Array.isArray(parsed.corps)) {
            // On convertira ce cas complexe plus bas, on garde l'objet tel quel pour l'instant
            content = parsed; 
        } 
        // Gestion du cas simple { "email": "..." }
        else {
            let keys = Object.keys(parsed);
            let bodyKey = keys.find(k => k.includes('corps') || k.includes('body') || k.includes('email') || k.includes('message') || k.includes('text'));

            if (bodyKey) {
                content = parsed[bodyKey];
            } else if (keys.length > 0) {
                // Fallback : première valeur
                content = parsed[keys[0]];
            }
        }
    } else {
        // Si c'était juste une string encodée (ex: "\"Salut\\nCa va\""), le parse l'a nettoyée
        content = parsed;
    }
} catch (e) {
    // Ce n'était pas du JSON, on garde le texte tel quel
}

// Si on se retrouve avec un objet complexe (le cas du tableau structuré), on le traite à part
let isComplexJson = (typeof content === 'object' && content.corps && Array.isArray(content.corps));
let bodyMarkdown = "";
let subject = "🚀 Votre parcours vers l'autonomie financière avec Educfinance";
let htmlContent = "";

if (isComplexJson) {
    // --- MOTEUR DE RENDU JSON COMPLEXE ---
    if (content.objet || content.subject) subject = content.objet || content.subject;

    content.corps.forEach(bloc => {
        if (['paragraphe', 'salutation', 'signature', 'texte'].includes(bloc.type)) {
            htmlContent += `<p style="margin-bottom: 10px; line-height: 1.6;">${bloc.contenu.replace(/\n/g, '<br>')}</p>`;
        } else if (bloc.type === 'titre') {
            htmlContent += `<h3 style="color: #333; margin-top: 20px; margin-bottom: 10px;">${bloc.contenu}</h3>`;
        } else if (bloc.type.includes('liste')) {
            htmlContent += '<ul style="margin-bottom: 20px;">';
            if (Array.isArray(bloc.contenu)) bloc.contenu.forEach(item => htmlContent += `<li style="margin-bottom: 5px;">${item}</li>`);
            htmlContent += '</ul>';
        } else if (bloc.type.includes('tableau')) {
            htmlContent += '<table cellspacing="0" cellpadding="0" style="width: 100%; border-collapse: collapse; margin: 25px 0; font-family: Helvetica, Arial, sans-serif; font-size: 14px;">';
            if (Array.isArray(bloc.contenu) && bloc.contenu.length > 0) {
                let headers = Object.values(bloc.contenu[0]);
                htmlContent += '<thead><tr>';
                headers.forEach(h => htmlContent += `<th style="text-align: left; padding: 12px 5px; border-bottom: 2px solid #000; font-weight: normal; color: #333;">${h}</th>`);
                htmlContent += '</tr></thead><tbody>';
                for (let i = 1; i < bloc.contenu.length; i++) {
                    let row = Object.values(bloc.contenu[i]);
                    htmlContent += '<tr>';
                    row.forEach((cell, index) => {
                        let cellContent = cell;
                        if (index === 0) cellContent = `<strong>${cellContent}</strong>`;
                        htmlContent += `<td style="padding: 12px 5px; border-bottom: 1px solid #ddd; vertical-align: top;">${cellContent}</td>`;
                    });
                    htmlContent += '</tr>';
                }
                htmlContent += '</tbody></table>';
            }
        }
    });
} else {
    // --- TRAITEMENT TEXTE BRUT (Ton cas actuel) ---
    // On s'assure que c'est une string
    if (typeof content !== 'string') content = JSON.stringify(content);

    // NETTOYAGE FINAL DES RÉSIDUS
    bodyMarkdown = content;
    // Enlève les guillemets de début/fin s'ils sont revenus
    bodyMarkdown = bodyMarkdown.replace(/^"|"$/g, '');
    // Transforme les \n littéraux en vrais sauts de ligne
    bodyMarkdown = bodyMarkdown.split('\\n').join('\n');
    bodyMarkdown = bodyMarkdown.trim();

    // Extraction sujet
    const subjectMatch = bodyMarkdown.match(/^(Subject|Sujet)\s*:\s*(.*)/i);
    if (subjectMatch) {
        const firstLineEnd = bodyMarkdown.indexOf('\n');
        if (firstLineEnd !== -1) {
            subject = bodyMarkdown.substring(0, firstLineEnd).replace(/^(Subject|Sujet)\s*:\s*/i, '').trim();
            bodyMarkdown = bodyMarkdown.substring(firstLineEnd).trim();
        }
    }

    // Conversion Markdown -> HTML
    let lines = bodyMarkdown.split('\n');
    let inList = false, inTable = false;

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i].trim();
        if ((line.startsWith('* ') || line.startsWith('- ')) && !inTable) {
            if (!inList) { htmlContent += '<ul style="margin-bottom: 20px;">'; inList = true; }
            htmlContent += `<li style="margin-bottom: 8px;">${line.substring(2).trim()}</li>`;
        } else if (line.includes('|')) {
            if (line.replace(/\|/g, '').replace(/-/g, '').replace(/:/g, '').trim() === '') continue;
            if (!inTable) {
                htmlContent += '<div style="text-align: center; margin: 25px 0;"><table cellspacing="0" cellpadding="0" style="width: auto; margin: 0 auto; border-collapse: collapse; font-family: Helvetica, Arial, sans-serif; font-size: 14px; display: inline-table;"><thead><tr>';
                let cells = line.split('|').filter(c => c.trim() !== '');
                for (let cell of cells) htmlContent += `<th style="text-align: left; padding: 10px 20px; border-bottom: 2px solid #000; font-weight: bold; color: #333; white-space: nowrap;">${cell.trim()}</th>`;
                htmlContent += '</tr></thead><tbody>';
                inTable = true;
            } else {
                htmlContent += '<tr>';
                let cells = line.split('|').filter(c => c.trim() !== '');
                cells.forEach((cell, index) => {
                    let cellContent = cell.trim();
                    // Fix Date
                    const dateMatch = cellContent.match(/(\d{4})-(\d{2})-(\d{2})/);
                    if (dateMatch) {
                        const [, year, month, day] = dateMatch;
                        const dateObj = new Date(year, month - 1, day);
                        const options = { day: 'numeric', month: 'long', year: 'numeric' };
                        cellContent = "Le " + dateObj.toLocaleDateString('fr-FR', options);
                    }
                    if (index === 0) cellContent = `<strong>${cellContent}</strong>`;
                    htmlContent += `<td style="padding: 10px 20px; border-bottom: 1px solid #ddd; vertical-align: top; text-align: left;">${cellContent}</td>`;
                });
                htmlContent += '</tr>';
            }
        } else {
            if (inList) { htmlContent += '</ul>'; inList = false; }
            if (inTable) { htmlContent += '</tbody></table></div>'; inTable = false; }
            if (line.length > 0) htmlContent += `<p style="margin-bottom: 10px;">${line}</p>`;
        }
    }
    if (inList) htmlContent += '</ul>';
    if (inTable) htmlContent += '</tbody></table></div>';
}

// --- FINITIONS ---
htmlContent = htmlContent.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
htmlContent = htmlContent.replace(
    /👉 \[INSCRIPTION ICI\]\(([^)]+)\)/g, 
    '<p style="margin-top: 20px; text-align: left;">👉 <a href="$1" style="color: #0000FF; font-weight: bold; text-decoration: underline; font-size: 16px;">INSCRIPTION ICI</a></p>'
);
htmlContent = htmlContent.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color: #0000FF;">$1</a>');

// Fix Prénom
const prenomProspect = $('Parsing variables du profiling').item.json.identite.prenom || "Cher client";
htmlContent = htmlContent.replace(/Bonjour \[Prénom\],/gi, `Bonjour ${prenomProspect},`);
htmlContent = htmlContent.replace(/Salut \[Prénom\],/gi, `Salut ${prenomProspect},`);

// Signature
htmlContent = htmlContent.replace('[Ton Prénom]', 'Djamel');
htmlContent = htmlContent.replace('[Votre Prénom]', 'Djamel');

// Temps
let duration = "N/A";
try {
    const startTime = new Date($('On form submission').item.json.submittedAt).getTime();
    const endTime = new Date().getTime();
    duration = ((endTime - startTime) / 1000).toFixed(1);
} catch(e) {}

const finalHtml = `<div style="font-family: Helvetica, Arial, sans-serif; font-size: 15px; line-height: 1.6; color: #333;">
${htmlContent}
<br>
<hr style="border: 0; border-top: 1px solid #eee; margin: 30px 0;">
<p style="color: #aaa; font-size: 11px;">
    ⚡ Généré en ${duration}s
</p>
</div>`;

return {
  email_subject: subject,
  email_body: finalHtml
};

// FORCE la lecture du nœud de Profiling (on remonte la chaîne)
const p = $('Parsing variables du profiling').item.json;

const prenom = p.identite?.prenom || "Prospect";
const situation = p.situation_financiere?.epargne_investissements || "Non spécifié";
const dettes = p.situation_financiere?.dettes || "Non spécifié";
const profession = p.situation_professionnelle?.profession || "Non spécifié";
const objectif = p.objectifs_projets?.objectif_principal || "Non spécifié";
const cohorte = p.logistique?.dates_souhaitees || "Non spécifié";
const contraintes = p.logistique?.contraintes || "Non spécifié";

let noteHtml = `<b>📝 SYNTHÈSE APPEL - ${prenom.toUpperCase()}</b><br><br>`;
noteHtml += `<b>💰 Situation :</b> ${situation} (Dettes: ${dettes})<br>`;
noteHtml += `<b>💼 Pro :</b> ${profession}<br><br>`;
noteHtml += `<b>🔥 Douleurs :</b><br><ul>`;
if (p.points_douloureux) p.points_douloureux.forEach(pt => noteHtml += `<li>${pt}</li>`);
noteHtml += `</ul><b>🎯 Objectifs :</b> ${objectif}<br><br>`;
noteHtml += `<b>📅 Logistique :</b><br>• Cohorte : ${cohorte}<br>• Contraintes : ${contraintes}<br>`;

// Remplacement de "analyste" par Djamel
noteHtml = noteHtml.replace(/analyste/gi, '<b>Djamel</b>');

return { pipedrive_note: noteHtml, prospect_name: prenom };

const rawText = $input.first().json.content.parts[0].text;
const cleanText = rawText.replace(/```json|```/g, '').trim();
return JSON.parse(cleanText);

// 1. Récupère le Score (Remonte au tronc commun)
const scoring = $('Mettre en variable le scoring output').item.json;

// 2. Récupère l'ID du Deal (Depuis le nœud HTTP juste avant la sauvegarde)
const dealId = $('Prospect opty retrieval').item.json.data[0].id;

let probability = Math.round(scoring.score_global * 10);

let noteHtml = `<b>🤖 SCORING IA : ${scoring.score_global}/10</b><br><br>`;
const c = scoring.details_criteres;
noteHtml += `<b>💰 Budget :</b> ${c.budget.note}/10<br><i>${c.budget.preuve}</i><br><br>`;
noteHtml += `<b>🚨 Urgence :</b> ${c.urgence.note}/10<br><i>${c.urgence.preuve}</i><br><br>`;
noteHtml += `<b>💡 Recommandation :</b><br>`;
if (scoring.analyse.actions_recommandees) {
    scoring.analyse.actions_recommandees.forEach(a => noteHtml += `• ${a}<br>`);
}

noteHtml = noteHtml.replace(/analyste/gi, '<b>Djamel</b>');

return { deal_id: dealId, probability: probability, note_content: noteHtml };

// 1. Récupérer le texte de la partie 1
// On utilise le nom exact vu dans ton interface
const text1 = $('Audio trascription - part 1').item.json.text || "";

// 2. Récupérer le texte de la partie 2
let text2 = "";
try {
    // On utilise le nom exact vu dans ton interface
    const part2 = $('Audio trascription - part 2').item.json.text;
    if (part2) {
        text2 = "\n\n[--- SUITE DE L'APPEL (PARTIE 2) ---]\n\n" + part2;
    }
} catch (e) {
    // Si le noeud n'a pas été exécuté (cas 1 seul fichier), on ignore l'erreur
}

return {
    text: text1 + text2
};

// 1. On récupère l'item complet qui arrive (pour garder le fichier binaire 'Audio')
const item = $input.first();

// 2. On récupère l'URL du webhook
// n8n remplit cette valeur selon la config du serveur (WEBHOOK_URL dans le .env)
const webhookUrl = $node["On form submission"].webhookUrl || "";

// 3. LOGIQUE DE DÉTECTION PRÉCISE
// On cherche spécifiquement le marqueur "-dev" pour le laptop.
// Si l'URL contient "n8n-dev", c'est le laptop -> tiny.
// Sinon, si c'est le domaine principal ou l'IP Oracle -> small.
let isProd = false;

if (webhookUrl.includes('n8n-dev')) {
    isProd = false; // C'est le laptop
} else if (webhookUrl.includes('dbflowtools.vip') || webhookUrl.includes('148.116')) {
    isProd = true;  // C'est la prod Oracle
} else {
    isProd = false; // Par défaut (ex: test local sans domaine), on reste sur tiny
}

// 4. On ajoute les informations au JSON de l'item
item.json.selected_model = isProd ? 'small' : 'tiny';
item.json.instance_type = isProd ? 'PRODUCTION' : 'DEVELOPPEMENT';
item.json.debug_url = webhookUrl;

// 5. On renvoie l'item ENTIER (JSON + Binaire Audio)
return item;
